1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientFilterBar, type ClientFilters } from '@/components/clients/ClientFilterBar'
10	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
11	import { SavedViewSwitcher, type ClientView } from '@/components/clients/SavedViewSwitcher'
12	import { SavedViewManager } from '@/components/clients/SavedViewManager'
13	import { ClientDrawer } from '@/components/clients/ClientDrawer'
14	import { Typography } from '@/components/ui/typography'
15	import dynamic from 'next/dynamic'
16	import { Skeleton } from '@/components/ui/skeleton'
17	
18	// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
19	const AddNoteModal = dynamic(
20	  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
21	  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
22	)
23	import { DataState } from '@/components/shared/DataState'
24	import { EmptyState } from '@/components/shared/EmptyState'
25	import { PageError } from '@/components/shared/PageError'
26	import { TableSkeleton } from '@/components/skeletons'
27	import { Alert, AlertDescription } from '@/components/ui/alert'
28	import type { ClientTag } from '@/components/clients/TagChip'
29	import type { Database } from '@/lib/supabase/types'
30	
31	type Client = Database['public']['Tables']['clients']['Row']
32	
33	interface ClientsPageClientProps {
34	  initialClients: Client[]
35	  tagLibrary: ClientTag[]
36	}
37	
38	const DEFAULT_FILTERS: ClientFilters = {
39	  q: '',
40	  tags: [],
41	  vip: false,
42	  inactive: false,
43	  noShows: false,
44	  showArchived: false,
45	  spendingTier: '',
46	  artistIds: [],
47	  serviceIds: [],
48	  lastVisitRange: '',
49	}
50	
51	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
52	  const router = useRouter()
53	  const searchParams = useSearchParams()
54	
55	  const [clients, setClients] = useState<Client[]>(initialClients)
56	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
57	  const [selectedIds, setSelectedIds] = useState<string[]>([])
58	  const [loading, setLoading] = useState(false)
59	  const [fetchError, setFetchError] = useState<Error | null>(null)
60	  const [drawerOpen, setDrawerOpen] = useState(false)
61	  const [editingClient, setEditingClient] = useState<Client | null>(null)
62	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
63	  const [page, setPage] = useState(1)
64	  const [hasMore, setHasMore] = useState(false)
65	  const [totalCount, setTotalCount] = useState<number | null>(null)
66	
67	  // Saved views
68	  const [views, setViews] = useState<ClientView[]>([])
69	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
70	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
71	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
72	  const [editingView, setEditingView] = useState<ClientView | null>(null)
73	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
74	
75	  const fetchViews = useCallback(async () => {
76	    try {
77	      const res = await fetch('/api/client-views')
78	      if (res.ok) {
79	        const json = await res.json() as { data: ClientView[] }
80	        setViews(json.data ?? [])
81	        // Auto-activate first system default view
82	        const defaultView = json.data?.find((v) => v.is_default)
83	        if (defaultView) {
84	          setActiveViewId((prev) => prev ?? defaultView.id)
85	        }
86	      }
87	    } catch {
88	      toast.error('Failed to load views', { description: 'Using All clients as default' })
89	    }
90	  }, [])
91	
92	  // Load saved views on mount
93	  useEffect(() => {
94	    void fetchViews()
95	  }, [fetchViews])
96	
97	  // Restore page from URL
98	  useEffect(() => {
99	    const p = parseInt(searchParams.get('page') ?? '1', 10)
100	    if (p > 1) {
101	      setPage(p)
102	    }
103	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
104	
105	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
106	    setLoading(true)
107	    setFetchError(null)
108	    try {
109	      const params = new URLSearchParams()
110	      if (f.q) params.set('q', f.q)
111	      if (f.tags.length) params.set('tags', f.tags.join(','))
112	      if (f.vip) params.set('vip', 'true')
113	      if (f.inactive) params.set('inactive', 'true')
114	      if (f.noShows) params.set('no_show', 'true')
115	      if (!f.showArchived) params.set('archived', 'false')
116	      else params.set('archived', 'any')
117	      if (f.spendingTier) params.set('spending', f.spendingTier)
118	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
119	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
120	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
121	      params.set('page', String(p))
122	      params.set('per_page', '50')
123	
124	      const res = await fetch(`/api/clients?${params.toString()}`)
125	      if (!res.ok) throw new Error('Failed to load clients')
126	      const json = await res.json() as { data: Client[]; count: number }
127	
128	      if (p === 1) {
129	        setClients(json.data ?? [])
130	      } else {
131	        setClients((prev) => [...prev, ...(json.data ?? [])])
132	      }
133	      setTotalCount(json.count ?? null)
134	      setHasMore((json.data?.length ?? 0) >= 50)
135	    } catch (err) {
136	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
137	    } finally {
138	      setLoading(false)
139	    }
140	  }, [])
141	
142	  useEffect(() => {
143	    void fetchClients(filters, 1)
144	    setPage(1)
145	    setSelectedIds([])
146	  }, [filters, fetchClients])
147	
148	  function handleFiltersChange(f: ClientFilters) {
149	    setFilters(f)
150	    setHasUnsavedChanges(true)
151	  }
152	
153	  function handleViewChange(viewId: string | null) {
154	    setActiveViewId(viewId)
155	    setHasUnsavedChanges(false)
156	    const view = views.find((v) => v.id === viewId)
157	    if (view) {
158	      // Apply view filters
159	      const viewFilters = view.filters as Partial<ClientFilters>
160	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
161	    } else {
162	      setFilters(DEFAULT_FILTERS)
163	    }
164	  }
165	
166	  async function handleDeleteView(viewId: string) {
167	    try {
168	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
169	      if (!res.ok) throw new Error('Failed to delete view')
170	      setViews((prev) => prev.filter((v) => v.id !== viewId))
171	      if (activeViewId === viewId) {
172	        const defaultView = views.find((v) => v.is_default)
173	        setActiveViewId(defaultView?.id ?? null)
174	      }
175	      toast.success('View deleted')
176	    } catch {
177	      toast.error('Failed to delete view')
178	    }
179	  }
180	
181	  async function handleDuplicateView(view: ClientView) {
182	    try {
183	      const res = await fetch('/api/client-views', {
184	        method: 'POST',
185	        headers: { 'Content-Type': 'application/json' },
186	        body: JSON.stringify({
187	          name: `${view.name} (copy)`,
188	          filters: view.filters,
189	          scope: 'private',
190	        }),
191	      })
192	      if (!res.ok) throw new Error('Failed to duplicate view')
193	      const json = await res.json() as { data: ClientView }
194	      setViews((prev) => [...prev, json.data])
195	      toast.success('View duplicated')
196	    } catch {
197	      toast.error('Failed to duplicate view')
198	    }
199	  }
200	
201	  function handleViewSaved(savedView: ClientView) {
202	    setViews((prev) => {
203	      const idx = prev.findIndex((v) => v.id === savedView.id)
204	      if (idx >= 0) {
205	        const next = [...prev]
206	        next[idx] = savedView
207	        return next
208	      }
209	      return [...prev, savedView]
210	    })
211	    setActiveViewId(savedView.id)
212	    setHasUnsavedChanges(false)
213	  }
214	
215	  function handleLoadMore() {
216	    const nextPage = page + 1
217	    setPage(nextPage)
218	    router.replace(`?page=${nextPage}`, { scroll: false })
219	    void fetchClients(filters, nextPage)
220	  }
221	
222	  function handleEditClient(client: Client) {
223	    setEditingClient(client)
224	    setDrawerOpen(true)
225	  }
226	
227	  function handleNewClient() {
228	    setEditingClient(null)
229	    setDrawerOpen(true)
230	  }
231	
232	  function handleDrawerSuccess(client: Client) {
233	    setClients((prev) => {
234	      const idx = prev.findIndex((c) => c.id === client.id)
235	      if (idx >= 0) {
236	        const next = [...prev]
237	        next[idx] = client
238	        return next
239	      }
240	      return [client, ...prev]
241	    })
242	  }
243	
244	  const hasActiveFilters = !!(
245	    filters.q || filters.tags.length > 0 || filters.vip ||
246	    filters.inactive || filters.noShows || filters.spendingTier ||
247	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
248	  )
249	
250	  const inactiveCount = useMemo(() => {
251	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
252	    return clients.filter(
253	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
254	    ).length
255	  }, [clients])
256	
257	  const activeView = views.find((v) => v.id === activeViewId) ?? null
258	  const isInitialLoad = loading && clients.length === 0
259	
260	  return (
261	    <div className="flex flex-col gap-4 p-4 lg:p-6">
262	      {/* Header */}
263	      <div className="flex items-center justify-between">
264	        <div className="flex items-center gap-3">
265	          <div>
266	            <Typography variant="h1">Clients</Typography>
267	            <p className="text-sm text-muted-foreground mt-0.5">
268	              {totalCount !== null ? (
269	                <span className="tabular-nums">
270	                  {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
271	                </span>
272	              ) : clients.length > 0 ? (
273	                <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
274	              ) : null}
275	            </p>
276	          </div>
277	          {inactiveCount > 0 && (
278	            <span
279	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
280	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-xs font-medium px-2 py-0.5 select-none"
281	            >
282	              <span className="h-2 w-2 rounded-full bg-destructive shrink-0" aria-hidden="true" />
283	              {inactiveCount} inactive
284	            </span>
285	          )}
286	        </div>
287	        <Button onClick={handleNewClient}>
288	          <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
289	          New client
290	        </Button>
291	      </div>
292	
293	      {/* Saved views switcher */}
294	      {views.length > 0 && (
295	        <SavedViewSwitcher
296	          views={views}
297	          activeViewId={activeViewId}
298	          onViewChange={handleViewChange}
299	          onCreateView={() => {
300	            setViewManagerMode('create')
301	            setEditingView(null)
302	            setViewManagerOpen(true)
303	          }}
304	          onEditView={(view) => {
305	            setViewManagerMode('edit')
306	            setEditingView(view)
307	            setViewManagerOpen(true)
308	          }}
309	          onDuplicateView={handleDuplicateView}
310	          onDeleteView={handleDeleteView}
311	        />
312	      )}
313	
314	      {/* Unsaved changes banner */}
315	      {hasUnsavedChanges && activeView && !activeView.is_system && (
316	        <Alert className="py-2 border-amber-500/30 bg-amber-500/5">
317	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
318	            <span className="text-amber-700 dark:text-amber-400">
319	              Unsaved changes. Save view or discard?
320	            </span>
321	            <div className="flex gap-2 shrink-0">
322	              <Button
323	                size="sm"
324	                variant="outline"
325	                className="h-6 text-xs px-2"
326	                onClick={() => {
327	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
328	                  setHasUnsavedChanges(false)
329	                }}
330	              >
331	                Discard
332	              </Button>
333	              <Button
334	                size="sm"
335	                className="h-6 text-xs px-2"
336	                onClick={() => {
337	                  setViewManagerMode('edit')
338	                  setEditingView(activeView)
339	                  setViewManagerOpen(true)
340	                }}
341	              >
342	                Save view
343	              </Button>
344	            </div>
345	          </AlertDescription>
346	        </Alert>
347	      )}
348	
349	      <ClientFilterBar
350	        filters={filters}
351	        onChange={handleFiltersChange}
352	        tagLibrary={tagLibrary}
353	      />
354	
355	      {selectedIds.length > 0 && (
356	        <BulkActionsBar
357	          selectedIds={selectedIds}
358	          tagLibrary={tagLibrary}
359	          onClearSelection={() => setSelectedIds([])}
360	          onArchived={() => void fetchClients(filters, 1)}
361	          onTagsApplied={() => void fetchClients(filters, 1)}
362	        />
363	      )}
364	
365	      <DataState
366	        data={clients}
367	        isLoading={isInitialLoad}
368	        isError={!!fetchError && clients.length === 0}
369	        error={fetchError}
370	        loadingSlot={<TableSkeleton rows={8} />}
371	        emptySlot={
372	          hasActiveFilters ? (
373	            <EmptyState
374	              icon={SearchX}
375	              title="No clients match these filters"
376	              description="Try different filters or clear all to see everyone."
377	              cta={{ label: 'Clear filters', onClick: () => { setFilters(DEFAULT_FILTERS); setHasUnsavedChanges(false) } }}
378	              variant="no-results"
379	            />
380	          ) : activeView && activeViewId ? (
381	            <EmptyState
382	              icon={BookmarkX}
383	              title="No clients in this view"
384	              description={`The filters in "${activeView.name}" returned no results.`}
385	              cta={{
386	                label: 'Edit view filters',
387	                onClick: () => {
388	                  setViewManagerMode('edit')
389	                  setEditingView(activeView)
390	                  setViewManagerOpen(true)
391	                },
392	              }}
393	              variant="no-results"
394	            />
395	          ) : (
396	            <EmptyState
397	              icon={Users}
398	              title="No clients yet"
399	              description="Add your first client or import from CSV — they'll show up here as they book."
400	              cta={{ label: '+ Add client', onClick: handleNewClient }}
401	              variant="first-time"
402	            />
403	          )
404	        }
405	        errorSlot={
406	          <PageError
407	            error={fetchError ?? new Error('Failed to load clients')}
408	            reset={() => void fetchClients(filters, 1)}
409	            variant="inline"
410	          />
411	        }
412	      >
413	        {(data) => (
414	          <ClientsTable
415	            clients={data}
416	            tagLibrary={tagLibrary}
417	            loading={loading && data.length === 0}
418	            selectedIds={selectedIds}
419	            onSelectionChange={setSelectedIds}
420	            onEdit={handleEditClient}
421	            onAddNote={(id) => setNoteClientId(id)}
422	          />
423	        )}
424	      </DataState>
425	
426	      {/* Load more */}
427	      {(hasMore || loading) && clients.length > 0 && (
428	        <div className="flex items-center justify-between py-4">
429	          <span className="text-sm text-muted-foreground tabular-nums">
430	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
431	          </span>
432	          {hasMore && (
433	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
434	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
435	              Load more
436	            </Button>
437	          )}
438	        </div>
439	      )}
440	
441	      <ClientDrawer
442	        open={drawerOpen}
443	        onOpenChange={(v) => {
444	          setDrawerOpen(v)
445	          if (!v) setEditingClient(null)
446	        }}
447	        client={editingClient}
448	        tagLibrary={tagLibrary}
449	        onSuccess={handleDrawerSuccess}
450	      />
451	
452	      {noteClientId && (
453	        <AddNoteModal
454	          open={Boolean(noteClientId)}
455	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
456	          clientId={noteClientId}
457	        />
458	      )}
459	
460	      <SavedViewManager
461	        open={viewManagerOpen}
462	        onOpenChange={setViewManagerOpen}
463	        mode={viewManagerMode}
464	        view={editingView}
465	        currentFilters={filters}
466	        onSaved={handleViewSaved}
467	      />
468	    </div>
469	  )
470	}
